import React from 'react'
import {
  Input,
  Form,
  notification,
  Row,
  Col,
  InputNumber,
  Select,
  DatePicker
} from 'antd'
import moment from 'moment-timezone'
import { capitalizeFirstLetter } from '../../../../../helpers/utility'
import { get } from 'lodash'
// import DateTimePicker from 'react-datetime-picker'

export function getFormItems (formData) {
  const { getFieldDecorator } = this.props.form
  const { fieldName, type: Type, label = ' ', initialValue, idx } = formData

  const { type, fields = {} } = Type

  if (idx || idx === 0) {
    switch (type) {
      case 'int':
      case 'int64':
        return (
          <Form.Item label={label} key={idx}>
            {getFieldDecorator(fieldName, {
              initialValue: get(initialValue, fieldName, '')
            })(<InputNumber />)}
          </Form.Item>
        )
      case 'float64':
        return (
          <Form.Item label={label} key={idx}>
            {getFieldDecorator(fieldName, {
              initialValue: get(initialValue, fieldName, '')
            })(<InputNumber step='any' />)}
          </Form.Item>
        )
      case 'string': {
        const options = formData?.type?.options
        if (options && Array.isArray(options)) {
          return (
            <Form.Item label={label} key={idx}>
              {getFieldDecorator(fieldName, {
                initialValue: get(initialValue, fieldName, '')
              })(
                <Select
                  showSearch
                  placeholder=''
                  className='dropdown-input'
                  filterOption={(input, option) =>
                    option.props.children
                      .toLowerCase()
                      .indexOf(input.toLowerCase()) >= 0}
                >
                  {options?.length > 0 &&
                    options.map((option, index) => {
                      return (
                        <Select.Option
                          key={index}
                          value={option.key ? option.key : option}
                        >
                          {option.value ? option.value : option}
                        </Select.Option>
                      )
                    })}
                </Select>
              )}
            </Form.Item>
          )
        }
        return (
          <Form.Item label={label} key={idx}>
            {getFieldDecorator(fieldName, {
              initialValue: get(initialValue, fieldName, '')
            })(<Input disabled={fieldName === 'reference_id'} />)}
          </Form.Item>
        )
      }
      case 'object': {
        const parentKeyLocal = fieldName
        return (
          <Row key={idx} type='flex' justify='space-around'>
            {label && (
              <Col span={24}>
                <h4>
                  <b>{label}</b>
                </h4>
              </Col>
            )}
            {Object.keys(fields)?.length > 0 &&
              Object.keys(fields).map((item, index) => {
                const data = getFormItems.call(this, {
                  fieldName: `${parentKeyLocal}.${item}`,
                  type: fields[item],
                  label: capitalizeFirstLetter(item),
                  initialValue: initialValue,
                  required: true,
                  idx: index,
                  key: `${item}-${idx}-${index}`
                })
                return <Col key={index}>{data}</Col>
              })}
          </Row>
        )
      }
      case 'array': {
        const parentKeyLocal = fieldName
        return (
          <Row type='flex' key={idx}>
            <Col span={24}>
              {label && (
                <Col span={24}>
                  <h4>
                    <b>{label}</b>
                  </h4>
                </Col>
              )}
            </Col>
            <Col className='scrollable-table'>
              <table className='tableStyle'>
                <tr className='tableRow'>
                  {Object.keys(fields)?.length > 0 &&
                    Object.keys(fields).map((item, index) => {
                      const labelNode = (
                        <th className='tableHead'>
                          <b>{capitalizeFirstLetter(item)}</b>
                        </th>
                      )
                      return (
                        <td key={index} className='tableData'>
                          {labelNode}
                        </td>
                      )
                    })}
                </tr>
                {get(initialValue, fieldName, [])?.length > 0 &&
                  get(initialValue, fieldName, []).map((initialItem, index) => (
                    <tr className='tableRow' key={index}>
                      {Object.keys(fields)?.length > 0 &&
                        Object.keys(fields).map((item, indexItem) => {
                          const data = getFormItems.call(this, {
                            fieldName: `${parentKeyLocal}[${index}].${item}`,
                            type: fields[item],
                            label: '',
                            initialValue: initialValue,
                            required: true,
                            idx: indexItem,
                            key: `${item}-${idx}-${indexItem}`
                          })
                          return (
                            <td key={index} className='tableData'>
                              {data}
                            </td>
                          )
                        })}
                    </tr>
                  ))}
              </table>
            </Col>
          </Row>
        )
      }
      case 'dob': {
        return (
          <Form.Item label={label} key={idx}>
            {getFieldDecorator(fieldName, {
              initialValue: get(initialValue, fieldName, '')
            })(
              <input type='text' /> // TODO : use datepicker instead of normal input
              // <DateTimePicker
              //   className='datetime-input'
              //   format='y-MM-dd'
              //   yearPlaceholder='YYYY'
              //   monthPlaceholder='MM'
              //   dayPlaceholder='DD'
              //   value={get(initialValue, formName, '')}
              // />
            )}
          </Form.Item>
        )
      }
      case 'date': {
        const value = initialValue[fieldName]
          ? moment(get(initialValue, fieldName, ''))
          : null
        return (
          <Form.Item label={label} key={idx}>
            {getFieldDecorator(fieldName, {
              initialValue: value
            })(
              <DatePicker
                format='YYYY-MM-DD'
                mode='date'
                showTime={{ format: 'YYYY-MM-DD' }}
              />
            )}
          </Form.Item>
        )
      }
      case 'datetime': {
        const value = initialValue[fieldName]
          ? moment(get(initialValue, fieldName, ''))
          : null
        return (
          <Form.Item label={label} key={idx}>
            {getFieldDecorator(fieldName, {
              initialValue: value
            })(
              <DatePicker
                format='YYYY-MM-DD HH:mm:ss'
                showTime={{ format: 'YYYY-MM-DD HH:mm:ss' }}
              />
            )}
          </Form.Item>
        )
      }
      case 'year': {
        const value = initialValue[fieldName]
          ? moment(get(initialValue, fieldName, ''))
          : null
        return (
          <Form.Item label={label} key={idx}>
            {getFieldDecorator(fieldName, {
              initialValue: value
            })(
              <DatePicker
                format='YYYY'
                mode='year'
                showTime={{ format: 'YYYY' }}
              />
            )}
          </Form.Item>
        )
      }
      default:
        return null
    }
  } else return null
}

export function errorHandler (error) {
  const { submitError, detailMessage, resetFunction } = error
  if (!submitError && detailMessage && detailMessage !== 'success') {
    if (Array.isArray(detailMessage)) {
      detailMessage.forEach((item) => {
        this.props.form.setFields({
          [item.key]: {
            value: item.val,
            errors: [
              new Error(
                item.key === 'beneficiary.ktp'
                  ? 'KTP minimum 16 characters'
                  : item.err
              )
            ]
          }
        })
      })
      resetFunction()
    } else {
      notification.error({
        message: 'Error',
        description: detailMessage
      })
      resetFunction()
    }
  }
}
